package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.domain.dto.finance.*;import com.punjab.oms.ar.base.ServiceException;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import javax.sql.DataSource;
import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-outbox-lease：隔离库租约并发及恢复测试。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.outbox-lease.real",matches="true") @EnabledIfSystemProperty(named="ar.outbox-lease.real.commit",matches="true")
class OutboxLeaseRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired JdbcTemplate jdbc;@Autowired DataSource dataSource;@Autowired OutboxLeaseService service;long scope;
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");for(String name:List.of("V002__ar_audit.sql","V011__ar_outbox.sql"))for(String sql:Files.readString(Path.of("../scratch/dbddl/"+name)).split(";"))if(!sql.isBlank())jdbc.execute(sql);scope=(UUID.randomUUID().getMostSignificantBits()>>>1)+10;}
 String token(){return UUID.randomUUID().toString();}
 long enqueue(){String key=token();jdbc.update("INSERT INTO oms_ar_lifecycle_event(event_type,occurred_at,actor,correlation_id,created_by,updated_by) VALUES('TEST',NOW(6),'lease-test',?,'lease-test','lease-test')",key);long event=jdbc.queryForObject("SELECT id FROM oms_ar_lifecycle_event WHERE correlation_id=?",Long.class,key);jdbc.update("INSERT INTO oms_ar_outbox(event_id,legal_entity_id,destination,payload,created_by,updated_by) VALUES(?,?,'FINANCE_EVENTS','{\"exact\":\"9999999999999999.12\"}','lease-test','lease-test')",event,scope);return jdbc.queryForObject("SELECT id FROM oms_ar_outbox WHERE event_id=?",Long.class,event);}
 OutboxClaimRequest request(String token,int max){return new OutboxClaimRequest(scope,token,max,30);}
 OutboxFinishRequest finish(long id,String token,boolean success,int max){return new OutboxFinishRequest(id,scope,token,success,success?null:"HTTP_503",max,60);}
 String status(long id){return jdbc.queryForObject("SELECT status FROM oms_ar_outbox WHERE id=?",String.class,id);}
 @Test @DisplayName("到期事件按ID领取，令牌确认成功仅生效一次")void success(){long id=enqueue();String token=token();var result=service.claim(request(token,3));assertThat(result).isNotNull();assertThat(result.id()).isEqualTo(id);assertThat(result.attemptCount()).isEqualTo(1);assertThat(result.payload()).contains("9999999999999999.12");assertThat(status(id)).isEqualTo("PROCESSING");assertThat(service.claim(request(token(),3))).isNull();assertThat(service.finish(finish(id,token(),true,3))).isFalse();assertThat(service.finish(finish(id,token,true,3))).isTrue();assertThat(service.finish(finish(id,token,true,3))).isFalse();var row=jdbc.queryForMap("SELECT * FROM oms_ar_outbox WHERE id=?",id);assertThat(row.get("status")).isEqualTo("SENT");assertThat(row.get("sent_time")).isNotNull();assertThat(row.get("lease_token")).isNull();assertThat(row.get("lease_until")).isNull();assertThat(row.get("last_error")).isNull();}
 @Test @DisplayName("失败进入延迟重试，耗尽后停止领取")void retries(){long id=enqueue();String first=token();assertThat(service.claim(request(first,2))).isNotNull();assertThat(service.finish(finish(id,first,false,2))).isTrue();assertThat(status(id)).isEqualTo("RETRY");assertThat(jdbc.queryForObject("SELECT TIMESTAMPDIFF(SECOND,NOW(6),next_attempt_at) FROM oms_ar_outbox WHERE id=?",Integer.class,id)).isBetween(55,60);assertThat(service.claim(request(token(),2))).isNull();jdbc.update("UPDATE oms_ar_outbox SET next_attempt_at=NOW(6) WHERE id=?",id);String second=token();assertThat(service.claim(request(second,2)).attemptCount()).isEqualTo(2);assertThat(service.finish(finish(id,second,false,2))).isTrue();assertThat(status(id)).isEqualTo("DEAD");assertThat(service.claim(request(token(),2))).isNull();assertThat(jdbc.queryForObject("SELECT last_error FROM oms_ar_outbox WHERE id=?",String.class,id)).isEqualTo("HTTP_503");}
 @Test @DisplayName("租约过期可重领，旧工作者不能确认")void expired(){long id=enqueue();String old=token();assertThat(service.claim(request(old,3))).isNotNull();jdbc.update("UPDATE oms_ar_outbox SET lease_until=DATE_SUB(NOW(6),INTERVAL 1 SECOND) WHERE id=?",id);assertThat(service.finish(finish(id,old,true,3))).isFalse();String next=token();assertThat(service.claim(request(next,3)).attemptCount()).isEqualTo(2);assertThat(service.finish(finish(id,old,false,3))).isFalse();assertThat(service.finish(finish(id,next,true,3))).isTrue();}
 @Test @DisplayName("最后一次领取崩溃后标记DEAD而非无限重发")void expiredExhaustion(){long id=enqueue();assertThat(service.claim(request(token(),1))).isNotNull();jdbc.update("UPDATE oms_ar_outbox SET lease_until=DATE_SUB(NOW(6),INTERVAL 1 SECOND) WHERE id=?",id);assertThat(service.claim(request(token(),1))).isNull();assertThat(status(id)).isEqualTo("DEAD");assertThat(jdbc.queryForObject("SELECT last_error FROM oms_ar_outbox WHERE id=?",String.class,id)).isEqualTo("LEASE_EXPIRED");}
 @Test @DisplayName("锁住队首时跳过，其他工作者领取下一条")void skipLocked()throws Exception{long first=enqueue(),second=enqueue();try(var c=dataSource.getConnection()){c.setAutoCommit(false);try(var s=c.prepareStatement("SELECT id FROM oms_ar_outbox WHERE id=? FOR UPDATE")){s.setLong(1,first);s.executeQuery().close();try(var executor=Executors.newSingleThreadExecutor()){var result=executor.submit(()->service.claim(request(token(),3))).get(5,TimeUnit.SECONDS);assertThat(result).isNotNull();assertThat(result.id()).isEqualTo(second);}}finally{c.rollback();}}assertThat(service.claim(request(token(),3)).id()).isEqualTo(first);}
 @Test @DisplayName("两个并发工作者不会取得同一事件")void concurrent()throws Exception{long id=enqueue();var gate=new CountDownLatch(1);try(var executor=Executors.newFixedThreadPool(2)){Callable<Long> action=()->{gate.await();var result=service.claim(request(token(),3));return result==null?null:result.id();};var a=executor.submit(action);var b=executor.submit(action);gate.countDown();assertThat(Arrays.asList(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS))).containsExactlyInAnyOrder(id,null);}assertThat(jdbc.queryForObject("SELECT attempt_count FROM oms_ar_outbox WHERE id=?",Integer.class,id)).isEqualTo(1);}
 @Test @DisplayName("不领取跨主体、其他目的地、已删除或未到期记录")void filters(){long id=enqueue();assertThat(service.claim(new OutboxClaimRequest(scope+1,token(),3,30))).isNull();jdbc.update("UPDATE oms_ar_outbox SET destination='OTHER' WHERE id=?",id);assertThat(service.claim(request(token(),3))).isNull();jdbc.update("UPDATE oms_ar_outbox SET destination='FINANCE_EVENTS',delete_status=true WHERE id=?",id);assertThat(service.claim(request(token(),3))).isNull();jdbc.update("UPDATE oms_ar_outbox SET delete_status=false,next_attempt_at=DATE_ADD(NOW(6),INTERVAL 1 HOUR) WHERE id=?",id);assertThat(service.claim(request(token(),3))).isNull();jdbc.update("UPDATE oms_ar_outbox SET next_attempt_at=NOW(6) WHERE id=?",id);String token=token();assertThat(service.claim(request(token,3))).isNotNull();assertThat(service.finish(new OutboxFinishRequest(id,scope+1,token,true,null,3,60))).isFalse();}
 @Test @DisplayName("内部请求边界校验，禁止异常详情入库")void invalid(){assertThatThrownBy(()->service.claim(null)).isInstanceOf(ServiceException.class);assertThatThrownBy(()->service.claim(new OutboxClaimRequest(scope,"bad",0,0))).isInstanceOf(ServiceException.class);assertThatThrownBy(()->service.finish(new OutboxFinishRequest(1L,scope,token(),false,"secret response",3,60))).isInstanceOf(ServiceException.class);assertThatThrownBy(()->service.finish(new OutboxFinishRequest(1L,scope,token(),false,null,3,60))).isInstanceOf(ServiceException.class);}
}
